    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '61: "Endometriosis" is defined as the presence of endometrial-like glands and stroma:', '["Within the myometrium", "Outside the uterine cavity", "In the blood only", "None"]', 1, 'Can affect almost any organ, but most commonly the pelvic peritoneum and ovaries. (ACOG)'),
    (v_topic_id, '62: Most widely accepted theory for the origin of endometriosis?', '["Coelomic metaplasia", "Retrograde Menstruation (Sampson theory)", "Lymphatic spread", "Iatrogenic"]', 1, 'Endometrial tissue travels through the tubes into the peritoneal cavity. (Williams Gynecology)'),
    (v_topic_id, '63: "Endometriosis" is a/an _____ dependent disease.', '["Androgen", "Estrogen", "Thyroid", "None"]', 1, 'Lesions contain estrogen receptors and aromatase, allowing for local estrogen production. (Beckmann)'),
    (v_topic_id, '64: What is the "Classic Triad" of endometriosis symptoms?', '["Fever, Pain, Rash", "Dysmenorrhea, Dyspareunia, and Infertility", "Bleeding, Bloating, Weight loss", "None"]', 1, 'The \"3 Ds.\" (ACOG)'),
    (v_topic_id, '65: The pain in endometriosis is typically _____ in nature.', '["Acute and sudden", "Cyclic and chronic, worsening just before and during menses", "Constant", "None"]', 1, 'Symptoms correlate with the menstrual cycle. (Williams)'),
    (v_topic_id, '66: Most common site for endometriosis?', '["Lungs", "Ovaries", "Bladder", "Appendix"]', 1, 'Often presents as "Chocolate cysts" (Endometriomas). (Beckmann)'),
    (v_topic_id, '67: "Endometrioma" on ultrasound appears as a cyst with:', '["Clear fluid", "Ground-glass (homogeneous low-level internal echoes)", "Solid nodes", "None"]', 1, 'Reflects old, hemolyzed blood. (ACOG)'),
    (v_topic_id, '68: What is the "Gold Standard" for the diagnosis of endometriosis?', '["Ultrasound", "Laparoscopy with direct visualization and/or biopsy", "MRI", "Blood test"]', 1, 'Requires surgical confirmation. (Williams)'),
    (v_topic_id, '69: Characteristic appearance of peritoneal endometriosis lesions?', '["White only", "Gunpowder burn (blue-black or red) or Powder-burn lesions", "Green", "None"]', 1, 'Reflects different stages of activity and hemorrhage. (Beckmann)'),
    (v_topic_id, '70: "Fitz-Hugh-Curtis" syndrome (liver capsule adhesions) is associated with PID, while endometriosis adhesions in the pelvis are called:', '["Stickers", "Powder-burns", "Adhesions (often causing a \"frozen pelvis\")", "None"]', 2, 'Severe scarring can distort anatomy and cause chronic pain. (Williams)'),
    (v_topic_id, '71: "Endometriosis" - Is the "severity of symptoms" always correlated with the "stage of disease"?', '["Yes", "No (Stage I can be very painful, Stage IV can be asymptomatic)", "Only in GDM", "None"]', 1, 'Poor correlation between physical findings and pain level. (ACOG)'),
    (v_topic_id, '72: Management of "Suspected" endometriosis in a patient with mild symptoms?', '["Immediate surgery", "Empiric medical therapy (NSAIDs and OCPs)", "Wait and see", "None"]', 1, 'A common first-line approach. (Beckmann)'),
    (v_topic_id, '73: "NSAIDs" help in endometriosis by:', '["Removing the tissue", "Inhibiting prostaglandin synthesis", "Increasing estrogen", "None"]', 1, 'Targets the inflammatory component of the pain. (ACOG)'),
    (v_topic_id, '74: "Combined Oral Contraceptives" (OCPs) treat endometriosis by:', '["Inducing ovulation", "Suppressing ovulation and causing decidualization/atrophy of the endometrial tissue", "Increasing bleeding", "None"]', 1, 'Thins out the ectopic lining. (Williams)'),
    (v_topic_id, '75: "Progestin-only" therapy (e.g., Norethindrone or Mirena IUD) is:', '["Ineffective", "Effective for symptom relief by causing atrophy of lesions", "Dangerous", "None"]', 1, 'Useful for those who cannot take estrogen. (Beckmann)'),
    (v_topic_id, '76: "GnRH Agonists" (e.g., Leuprolide) treat endometriosis by:', '["Increasing LH/FSH", "Creating a reversible \"pseudo-menopause\" (hypoestrogenic state)", "Fixing the genes", "None"]', 1, 'Starves the estrogen-dependent lesions. (ACOG)'),
    (v_topic_id, '77: "Danazol" is an older treatment for endometriosis. Its mechanism is:', '["Estrogenic", "Androgenic (suppresses the pituitary-ovarian axis)", "Progestogen", "None"]', 1, 'Effective but limited by significant virilizing side effects (weight gain, hair growth). (Williams)'),
    (v_topic_id, '78: "Endometriosis" and Infertility: What is a possible mechanism?', '["Anatomic distortion (adhesions blocking the tubes)", "Hostile peritoneal environment (inflammation affecting sperm/oocyte)", "Endocrine dysfunction", "All of the above"]', 3, 'Complex multifactorial cause of subfertility. (ACOG)'),
    (v_topic_id, '79: Surgical management for endometriosis in a woman DESIRING fertility?', '["Hysterectomy", "Laparoscopic ablation or excision of lesions and lysis of adhesions", "Radiation", "None"]', 1, 'Goal is to restore anatomy and reduce pain. (Beckmann)'),
    (v_topic_id, '80: Definitive surgical treatment for endometriosis?', '["Myomectomy", "Total Hysterectomy and Bilateral Salpingo-Oophorectomy (BSO)", "Appendectomy", "None"]', 1, 'Removes the uterus and the primary source of estrogen (ovaries). (ACOG)'),
    (v_topic_id, '81: "Aromatase Inhibitors" (e.g., Letrozole) are used in endometriosis because:', '["They increase estrogen", "Lesions produce their own estrogen via aromatase; inhibitors block this local production", "They help sleep", "None"]', 1, 'Used in refractory cases. (Williams)'),
    (v_topic_id, '82: "Deep Infiltrating Endometriosis" (DIE) involves tissue extending > _____ mm beneath the peritoneum.', '["1", "3", "5", "10"]', 2, 'Associated with more severe pain and organ dysfunction (bowel/bladder). (Beckmann)'),
    (v_topic_id, '83: "Endometriosis" of the Ureter can cause:', '["Diabetes", "Hydronephrosis and silent renal loss", "Infection", "None"]', 1, 'Requires careful assessment in DIE. (Williams)'),
    (v_topic_id, '84: "Endometriosis" of the Bowel most commonly affects the:', '["Small intestine", "Rectosigmoid colon", "Appendix", "Stomach"]', 1, 'Presents with dyschezia (painful defecation). (Beckmann)'),
    (v_topic_id, '85: "Catamenial Pneumothorax" is a rare manifestation of endometriosis where:', '["The lung collapses during menses due to diaphragmatic or pleural lesions", "The baby kicks the lung", "Smoking", "None"]', 0, 'Classic high-yield board fact. (Williams)'),
    (v_topic_id, '86: Risk factors for Endometriosis?', '["Early menarche, short cycles (< 27 days), and nulliparity", "Multiple births", "Smoking (protective effect)", "Both A and C"]', 3, 'More menstrual cycles = more risk. Smoking reduces estrogen. (ACOG)'),
    (v_topic_id, '87: "Coelomic Metaplasia" theory suggests that:', '["Blood travels back", "Peritoneal mesothelial cells differentiate into endometrial tissue", "Cancer", "None"]', 1, 'Explains endometriosis in patients without menses. (Beckmann)'),
    (v_topic_id, '88: A "Chocolate Cyst" is another name for:', '["Dermoid", "Endometrioma", "Follicular cyst", "None"]', 1, 'Named for the appearance of the old blood within it. (Williams)'),
    (v_topic_id, '89: "Stage I" Endometriosis (revised ASRM):', '["Severe adhesions", "Minimal disease (isolated lesions, no significant adhesions)", "Bilateral endometriomas", "None"]', 1, 'Standard staging system. (ACOG)'),
    (v_topic_id, '90: "Stage IV" Endometriosis:', '["Minor spots", "Severe disease with large endometriomas and extensive dense adhesions (frozen pelvis)", "Normal", "None"]', 1, 'Highest severity level. (Williams)'),
    (v_topic_id, '91: "Endometriosis" - Is CA-125 a useful diagnostic test?', '["Yes, for screening", "No, it may be elevated but lacks specificity and sensitivity for diagnosis", "Only in pregnancy", "None"]', 1, 'Not recommended for routine use in endometriosis. (Beckmann)'),
    (v_topic_id, '92: Can "Men" get endometriosis?', '["Absolutely not", "Yes, extremely rare cases reported in men on high-dose estrogen for prostate cancer", "Only if they have twins", "None"]', 1, 'Supports the coelomic metaplasia theory. (Williams)'),
    (v_topic_id, '93: "Malignant Transformation" of endometriosis?', '["Never", "Risk is < 1%; most commonly Clear Cell or Endometrioid ovarian cancer", "100%", "None"]', 1, 'Ovarian cancer association. (ACOG)'),
    (v_topic_id, '94: Does "Hysterectomy" alone cure endometriosis if the ovaries are left behind?', '["Yes", "No, the remaining ovaries continue to stimulate any residual ectopic tissue", "Only in teens", "None"]', 1, 'High recurrence risk without BSO. (Beckmann)'),
    (v_topic_id, '95: "Dyspareunia" in endometriosis is typically:', '["Superficial", "Deep (due to traction on the uterosacral ligaments)", "Painless", "None"]', 1, 'Physical finding of a "fixed, retroverted uterus" and "uterosacral nodularity." (Williams)'),
    (v_topic_id, '96: "Dyschezia" (pain with bowel movements) suggests endometriosis in the:', '["Bladder", "Rectovaginal septum or Pouch of Douglas", "Small bowel", "None"]', 1, 'Often cyclic. (Beckmann)'),
    (v_topic_id, '97: "Endometriosis" - "Adhesion" formation is due to:', '["Infection", "Chronic inflammation and bleeding into the peritoneal cavity", "Surgery only", "None"]', 1, 'Results in scarring between organs. (Williams)'),
    (v_topic_id, '98: "Infertility" - Does surgical removal of MINIMAL endometriosis improve pregnancy rates?', '["No", "Yes, significantly (though the mechanism is unclear)", "Only in GDM", "None"]', 1, 'Proven in several large trials. (ACOG)'),
    (v_topic_id, '99: "Mirena" IUD is approved for treatment of:', '["Endometriosis pain", "Heavy menstrual bleeding (but often used off-label for endometriosis)", "Cancer", "None"]', 1, 'Highly effective for pelvic pain. (Beckmann)'),
    (v_topic_id, '100: "Endometriosis" - Is it a "Pre-cancerous" condition?', '["Yes", "No, but it shares some molecular features with cancer and has a small risk of transformation", "Only in smokers", "None"]', 1, 'Usually considered benign but aggressive. (Williams)'),
    (v_topic_id, '101: "PCOS" (Polycystic Ovary Syndrome) is a/an _____ disorder.', '["Infectious", "Endocrine and Metabolic", "Genetic only", "None"]', 1, 'Most common endocrine disorder in women of reproductive age. (ACOG)'),
    (v_topic_id, '102: "Rotterdam Criteria" for PCOS requires 2 of 3:', '["Obesity, Pain, Bleeding", "Hyperandrogenism, Ovulatory Dysfunction (Oligo/Anovulation), and PCO on ultrasound", "Twins, GDM, HTN", "None"]', 1, 'Current global standard for diagnosis. (ACOG)'),
    (v_topic_id, '103: "Hyperandrogenism" in PCOS presents clinically as:', '["Hirsutism, acne, and male-pattern alopecia", "Weight loss", "Tall stature", "None"]', 0, 'Excessive terminal hair in a male distribution. (Beckmann)'),
    (v_topic_id, '104: "Hirsutism" is scored using which system?', '["Gleason", "Ferriman-Gallwey Score", "Bishop", "None"]', 1, 'Assess 9 body areas for hair growth. (Williams)'),
    (v_topic_id, '105: "Oligo/Anovulation" in PCOS typically presents as:', '["Normal cycles", "Irregular, infrequent cycles (Oligomenorrhea) or Amenorrhea", "Heavy bleeding every 28 days", "None"]', 1, 'Leading to subfertility. (ACOG)'),
    (v_topic_id, '106: "Polycystic Ovaries" on ultrasound (the \"String of Pearls\") is defined as:', '["1 cyst", ">= 12 follicles (2-9mm) or increased ovarian volume (> 10 mL)", "Cancer", "None"]', 1, 'Updated criteria use >= 20 follicles with modern machines. (Beckmann)'),
    (v_topic_id, '107: "Insulin Resistance" is present in what percentage of women with PCOS?', '["1%", "Up to 50-70% (especially if obese)", "100%", "None"]', 1, 'Key driver of hyperandrogenism. (Williams)'),
    (v_topic_id, '108: Why does high "Insulin" increase "Androgens"?', '["It kills the liver", "It stimulates ovarian theca cells to produce androgens and decreases SHBG levels in the liver", "It increases estrogen", "None"]', 1, 'More free testosterone becomes available. (ACOG)'),
    (v_topic_id, '109: "PCOS" - What happens to the "LH/FSH" ratio?', '["Stays same", "It is often increased (Classic ratio > 2:1 or 3:1)", "Decreased", "None"]', 1, 'Reflects the neuroendocrine dysfunction. (Beckmann)'),
    (v_topic_id, '110: Women with PCOS are at a higher risk for which metabolic conditions?', '["Type 2 Diabetes and Metabolic Syndrome", "Obstructive Sleep Apnea", "Nonalcoholic Fatty Liver Disease (NAFLD)", "All of the above"]', 3, 'Requires long-term health screening. (ACOG)'),
    (v_topic_id, '111: Women with PCOS and long-standing amenorrhea are at high risk for:', '["Cervical cancer", "Endometrial Hyperplasia and Cancer (due to unopposed estrogen)", "Breast cancer", "None"]', 1, 'The lining builds up without progesterone-induced shedding. (Williams)'),
    (v_topic_id, '112: First-line management for a woman with PCOS who is OBESE and desires pregnancy?', '["IVF", "Weight loss and lifestyle modification", "Surgery", "None"]', 1, 'Even 5-10% weight loss can restore ovulation. (ACOG)'),
    (v_topic_id, '113: "Metformin" in PCOS works by:', '["Removing hair", "Improving insulin sensitivity and potentially lowering androgen levels", "Curing the genes", "None"]', 1, 'Used for metabolic health and sometimes for ovulation induction. (Beckmann)'),
    (v_topic_id, '114: First-line medication for "Ovulation Induction" in PCOS (current ACOG/ASRM recommendation)?', '["Clomiphene Citrate", "Letrozole (Aromatase Inhibitor)", "hCG", "None"]', 1, 'Letrozole has shown higher live birth rates in PCOS patients. (ACOG)'),
    (v_topic_id, '115: "Spironolactone" is used in PCOS for:', '["Inducing labor", "Treating hirsutism (Anti-androgenic effect)", "Birth control", "None"]', 1, 'Blocks androgen receptors and inhibits 5-alpha reductase. (Williams)'),
    (v_topic_id, '116: "Spironolactone" MUST be used with contraception because:', '["It causes twins", "It is a teratogen (can feminize a male fetus)", "It causes weight gain", "None"]', 1, 'Important patient safety point. (Beckmann)'),
    (v_topic_id, '117: "Acanthosis Nigricans" is a skin sign of:', '["Infection", "Insulin Resistance", "Cancer", "None"]', 1, 'Velvety, hyperpigmented patches in intertriginous areas (neck, axilla). (Williams)'),
    (v_topic_id, '118: "PCOS" - What happens to "Sex Hormone Binding Globulin" (SHBG)?', '["Increases", "Decreases", "Stays same", "None"]', 1, 'Driven by high insulin; results in more free (active) testosterone. (Beckmann)'),
    (v_topic_id, '119: "Secondary Amenorrhea" is defined as no menses for _____ months in a woman with previously regular cycles.', '["1", "3", "6", "12"]', 1, 'Or 6 months in women with irregular cycles. (ACOG)'),
    (v_topic_id, '120: "Struma Ovarii" is a teratoma. "Endometrioma" is a cyst. "Theca Lutein" cysts are associated with moles. "PCOS" follicles are:', '["Malignant", "Atretic antral follicles", "Benign", "Both B and C"]', 3, 'Reflects the failure of a dominant follicle to emerge. (Williams)');
